"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import { createTreeController, Tree } from "@ui-sdk/react/tree"
import { useCallback, useMemo, useState, type FocusEvent, type ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { CommitBranchSelect } from "@/components/ui/commit-branch-select"
import { doneCount, Rows, summaryOf, treeItemsOf } from "@/components/ui/commit-history-rows"
import {
  commitHistory,
  type CommitHistoryChangeReason,
  type CommitHistoryController,
  type CommitHistoryOptions,
} from "@/components/ui/commit-history-primitive"
import {
  commitHistoryLabels,
  commitName,
  type CommitHistoryLabels,
  type CommitRowContext,
} from "@/components/ui/commit-history-row"
import { Select } from "@/components/ui/select"
import { useNow } from "@/components/ui/use-now"
import {
  useBranchModel,
  useCommitGraph,
  useCommitTrail,
  useFocusHead,
  useJustExpanded,
  useReachEnd,
} from "@/components/ui/use-commit-history"
import { useInstanceState } from "@/components/ui/use-instance-state"
import { useTrailRows } from "@/components/ui/use-trail-rows"
import type { BranchInfo, CommitBranch } from "@/lib/commit-branches"
import { rowOfCommit, type Commit } from "@/lib/commit-graph"
import { createCommitFinder, subjectPieces } from "@/lib/commit-message"
import { useLocale } from "@/lib/locale"
import type { Instant } from "@/lib/time"
import { cn } from "@/lib/utils"

type CommitHistoryProps = Omit<PartProps<"div">, "children" | "onSelect"> & {
  /** Names the history, for screen readers and agents. */
  "aria-label": string
  /** Newest first, children before parents: the order of `git log --topo-order`. */
  commits: readonly Commit[]
  /** The base branch; with `branches` and `onBranchChange`, a switcher chooses it. */
  branch?: string
  /**
   * Branch names for the switcher, or branches with their head (`{ name, head, tone?, ahead?, behind?,
   * updatedAt?, author? }`), which the branches view draws.
   */
  branches?: readonly (string | CommitBranch)[]
  onBranchChange?: CommitHistoryOptions["onBranchChange"]
  /** The count in the header; the finished commits loaded by default. Pass the server's total when paging. */
  count?: number
  /** Merges whose merged commits show, by id. Collapsed by default: one line per commit. */
  expanded?: readonly string[]
  defaultExpanded?: readonly string[]
  onExpandedChange?: CommitHistoryOptions["onExpandedChange"]
  /** Commits whose details show under their row. */
  details?: readonly string[]
  defaultDetails?: readonly string[]
  onDetailsChange?: CommitHistoryOptions["onDetailsChange"]
  /** `"single"` (default) keeps one commit's details open at a time. */
  detailsMode?: "single" | "multiple"
  /** Dims the rows other than the focused, hovered or open one. On while details are open by default. */
  focusMode?: boolean
  /** Click or Enter on a commit runs this instead of showing its details, for apps that navigate to a commit. */
  onOpenCommit?: (commit: Commit, details: ChangeDetails<CommitHistoryChangeReason>) => void
  onCopyHash?: CommitHistoryOptions["onCopyHash"]
  /** Older commits exist: a Load more button, and `onLoadMore` once the end scrolls into view. */
  hasMore?: boolean
  loadingMore?: boolean
  onLoadMore?: () => unknown
  /** One clock for every time in the list; a 30-second `useNow` by default. */
  now?: Instant
  locale?: string
  timeZone?: string
  labels?: Partial<CommitHistoryLabels>
  /** A row's estimated height in px before it is measured. Default 30. */
  estimateSize?: number
  /**
   * Find in page reaches commits scrolled out of view, by subject, through UI SDK's virtualizer and its findable
   * layers, built once the page is idle after its first paint. Off by default: on 50,000 commits it costs about a
   * frame on some held-arrow presses (p95 22-27 ms against 10 ms) and 10-40% on the first paint.
   */
  findable?: boolean
  /** Lanes the graph opens at most; an octopus merge's extra parents past it draw no lane. Default 12. */
  maxLanes?: number
  controller?: CommitHistoryController
  /** Content at the end of the header, before the count. */
  actions?: ReactNode
  /**
   * `"branches"` draws every active branch in `branches` as its own lane beside the base, coloured and labelled
   * at its head, with a select (or a press on a pill) to show one alone; merged branches stay folded under their merge. Commits are then
   * `git log --all --topo-order`. Default `"trail"`.
   */
  view?: "trail" | "branches"
  /** The branch in focus in the branches view: its head scrolled to and focused. */
  focusedBranch?: string | null
  onFocusedBranchChange?: CommitHistoryOptions["onFocusedBranchChange"]
  /** In the branches view, a branch in focus hides the other branches' commits. */
  filterBranch?: boolean
  /** A branch with no update for this long, in ms, shows as stale. Default 30 days. */
  staleAfter?: number
}

const noBranches: readonly CommitBranch[] = []

// oxlint-disable-next-line shadcn/no-arbitrary-values -- the scroller's cap with `findable` (UI SDK's virtualizer needs it bounded), and a lane's width
const trailWidths = "[--commit-history-height:40rem] [--commit-lane:0.875rem]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- a row's line at the reference frame's density, a touch target's height on a coarse pointer
const trailLine = "[--commit-line:1.875rem] pointer-coarse:[--commit-line:var(--control-height-touch)]"

/**
 * A commit trail, one line per commit: a graph lane per line of history, merges collapsed to one row whose
 * merged commits open on a side lane, and a commit's details inline under its row. Rows virtualize, the lanes
 * are laid out lazily from the top, and appending older pages costs only the new rows.
 */
function CommitHistory({
  "aria-label": label,
  commits,
  branch,
  branches,
  onBranchChange,
  count,
  expanded,
  defaultExpanded,
  onExpandedChange,
  details,
  defaultDetails,
  onDetailsChange,
  detailsMode,
  focusMode,
  onOpenCommit,
  onCopyHash,
  hasMore = false,
  loadingMore = false,
  onLoadMore,
  now: nowProp,
  locale: localeProp,
  timeZone,
  labels: labelOverrides,
  estimateSize = 30,
  findable = false,
  maxLanes,
  controller,
  actions,
  view = "trail",
  focusedBranch,
  onFocusedBranchChange,
  filterBranch = false,
  staleAfter,
  className,
  onFocus,
  ...props
}: CommitHistoryProps) {
  const labels = useMemo(() => ({ ...commitHistoryLabels, ...labelOverrides }), [labelOverrides])
  const locale = useLocale(localeProp)
  const now = useNow({ now: nowProp, intervalMs: 30_000 })

  const graph = useCommitGraph(commits)
  const branchList = useMemo(
    () => (branches ?? []).filter((entry): entry is CommitBranch => typeof entry !== "string"),
    [branches],
  )
  const branchNames = useMemo(
    () => branches?.map((entry) => (typeof entry === "string" ? entry : entry.name)),
    [branches],
  )
  const model = useBranchModel(graph, view === "branches" ? branchList : noBranches, { base: branch, staleAfter, now })
  const find = useMemo(() => createCommitFinder(graph), [graph])
  const nameContext = useMemo(() => ({ now, locale, labels }), [now, locale, labels])
  const lookup = useMemo(
    () => ({
      find,
      entries: () =>
        graph.commits.map((commit) => ({
          value: commit.id,
          label: commitName(commit, nameContext, model?.byHead.get(commit.id)),
        })),
      branches: () => (model?.all ?? []).map(summaryOf),
    }),
    [find, graph, nameContext, model],
  )

  const handle = usePrimitive(commitHistory, {
    lookup,
    expanded,
    defaultExpanded,
    onExpandedChange,
    details,
    defaultDetails,
    onDetailsChange,
    detailsMode,
    branch,
    branches: branchNames,
    onBranchChange,
    focusedBranch,
    onFocusedBranchChange,
    onCopyHash,
    controller,
    onOpenCommit: onOpenCommit
      ? (id, change) => {
          const row = rowOfCommit(graph, id)
          if (row !== undefined) onOpenCommit(graph.commits[row] as Commit, change)
        }
      : undefined,
  })
  const state = useInstanceState<typeof handle.state>(handle.instance)
  const activeIndex =
    model && state.focusedBranch ? model.active.findIndex((info) => info.name === state.focusedBranch) : -1
  const trail = useCommitTrail(graph, state.expanded, {
    maxLanes: maxLanes ?? (model ? 8 : undefined),
    model,
    only: filterBranch && activeIndex >= 0 ? activeIndex : undefined,
  })
  const { visible } = trail
  const justExpanded = useJustExpanded(state.expanded)
  const openDetails = useMemo(() => new Set(state.details), [state.details])
  const items = useMemo(() => treeItemsOf(graph), [graph])

  const commitAt = useCallback(
    (index: number) => graph.commits[visible.rows[index] as number] as Commit,
    [graph, visible],
  )
  const keyAt = useCallback((index: number) => commitAt(index).id, [commitAt])
  const textAt = useCallback((index: number) => subjectPieces(commitAt(index)), [commitAt])
  const { setScroller, anchor, ...virtual } = useTrailRows({
    count: visible.count,
    estimate: estimateSize,
    getKey: keyAt,
    text: textAt,
    findable,
  })

  // Stable, so the memoized branch select doesn't render its branches again on every move.
  const focusBranch = useCallback(
    (name: string | null) => handle.api.focusBranch(name, { reason: "item-press" }),
    [handle],
  )
  const context = useMemo<CommitRowContext>(
    () => ({
      now,
      locale,
      timeZone,
      labels,
      copied: state.copied,
      copyHash: (id, event) => void handle.api.copyHash(id, event),
      focusedBranch: state.focusedBranch,
    }),
    [now, locale, timeZone, labels, state.copied, handle, state.focusedBranch],
  )

  const [tree] = useState(() => createTreeController())
  const focusedInfo = model?.all.find((info) => info.name === state.focusedBranch)
  const headRow = focusedInfo ? rowOfCommit(graph, focusedInfo.head) : undefined
  useFocusHead(
    focusedInfo && headRow !== undefined
      ? { id: focusedInfo.head, position: visible.position[headRow] ?? -1 }
      : undefined,
    virtual.reveal,
    tree.focus,
  )
  const shownHeads = useMemo(() => {
    if (!model) return undefined
    const map = new Map<string, BranchInfo[]>()
    for (const info of model.all) {
      if (info.state === "merged") continue
      const list = map.get(info.head)
      if (list) list.push(info)
      else map.set(info.head, [info])
    }
    return map
  }, [model])

  const reachEnd = useReachEnd(onLoadMore, hasMore && !loadingMore)
  const total = count ?? doneCount(commits)
  const dimmed = focusMode ?? state.details.length > 0
  const switcher = branchNames && branchNames.length > 1 && onBranchChange

  return usePart(
    handle,
    "root",
    {},
    {
      ...props,
      "aria-label": label,
      ...({ "data-focus-mode": dimmed ? "" : undefined } as Record<`data-${string}`, string | undefined>),
      className: cn(
        "group/history flex min-h-0 min-w-0 flex-col gap-items rounded-surface border bg-card px-inset-item py-inset-item text-card-foreground shadow-surface",
        trailWidths,
        trailLine,
        className,
      ),
      onFocus: (event: FocusEvent<HTMLDivElement>) => {
        onFocus?.(event)
        if (!virtual.virtual || !(event.target instanceof Element)) return
        const index = Number(event.target.closest<HTMLElement>("[data-index]")?.dataset.index ?? Number.NaN)
        if (!Number.isNaN(index)) virtual.pin(index)
      },
      children: (
        <>
          <div
            data-slot="commit-history-header"
            className="flex min-w-0 items-center justify-between gap-items px-(--item-padding-x)"
          >
            {model && model.active.length > 0 ? (
              <CommitBranchSelect
                branches={model.active}
                focused={state.focusedBranch}
                onFocus={focusBranch}
                labels={labels}
                now={now}
                locale={locale}
              />
            ) : switcher ? (
              <Select
                aria-label={labels.branch}
                size="sm"
                options={branchNames.map((name) => ({ value: name, label: name }))}
                value={state.branch}
                onValueChange={(value) => {
                  if (typeof value === "string") handle.api.selectBranch(value, { reason: "item-press" })
                }}
                triggerProps={{
                  className:
                    "-ms-(--item-padding-x) w-auto border-transparent bg-transparent px-(--item-padding-x) font-medium shadow-none hover:bg-accent",
                }}
              />
            ) : (
              <span className="truncate text-body-sm font-medium">{state.branch ?? branch}</span>
            )}
            <span className="flex shrink-0 items-center gap-items">
              {actions}
              <span data-slot="commit-history-count" className="text-caption text-muted-foreground tabular-nums">
                {labels.commits(total, locale)}
              </span>
            </span>
          </div>
          <div
            ref={setScroller}
            className={cn("min-h-0 flex-1 overflow-y-auto", findable && "max-h-(--commit-history-height)")}
          >
            <div ref={anchor} className="min-w-0">
              <Tree
                aria-label={label}
                // The history's own actions serve agents by commit; the tree would list every row a second time.
                data-agent-hidden=""
                items={items}
                mode="none"
                expandOnPress={false}
                controller={tree}
                expanded={state.expanded as string[]}
                onExpandedChange={(next, change) =>
                  handle.api.setExpanded(next, {
                    reason: change.reason as CommitHistoryChangeReason,
                    event: change.event,
                  })
                }
                onAction={(id, { event }) => {
                  // A press inside a commit's details, like its copy button, is not a press on the row.
                  if (event?.target instanceof Element && event.target.closest("[data-slot=commit-details]")) return
                  // A press on a branch's pill shows only that branch, or every branch again when it's the one shown.
                  const pill =
                    event?.target instanceof Element ? event.target.closest<HTMLElement>("[data-branch]") : null
                  if (pill?.dataset.branch) {
                    const name = pill.dataset.branch
                    handle.api.focusBranch(state.focusedBranch === name ? null : name, { reason: "item-press", event })
                    return
                  }
                  const entry = find(id)
                  if (!entry) return
                  const options = { reason: "item-press" as const, event }
                  if (entry.merge) handle.api.toggle(id, options)
                  else if (onOpenCommit) handle.api.openCommit(id, options)
                  else handle.api.toggleDetails(id, options)
                }}
                onHighlight={(_id, { index }) => {
                  if (virtual.virtual && index >= 0) virtual.scrollToIndex(index)
                }}
                style={virtual.absolute ? { height: virtual.height } : undefined}
                className={cn("flex min-w-0 flex-col outline-none", virtual.virtual && "relative")}
              >
                <Rows
                  trail={trail}
                  details={openDetails}
                  justExpanded={justExpanded}
                  context={context}
                  virtual={virtual}
                  heads={shownHeads}
                />
              </Tree>
            </div>
            {hasMore && <div ref={reachEnd} aria-hidden="true" data-slot="commit-history-end" />}
          </div>
          {hasMore && onLoadMore && (
            <Button
              variant="ghost"
              size="sm"
              loading={loadingMore}
              className="self-center"
              onClick={() => onLoadMore()}
            >
              {labels.loadMore}
            </Button>
          )}
        </>
      ),
    },
  )
}

export { CommitHistory, commitHistoryLabels }
export type { CommitHistoryLabels, CommitHistoryProps }

"use client"

import { TreeItem, TreeItemIndicator, TreeItemLabel } from "@ui-sdk/react/tree"
import { ArrowDownIcon, ArrowUpIcon, CheckIcon, ChevronRightIcon, CopyIcon } from "lucide-react"
import { memo, useState, type CSSProperties, type ReactNode } from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { CommitGraphCell, graphColumns, laneColor, type CommitNodeKind } from "@/components/ui/commit-graph-cell"
import { GitBranchChip, GitFileChip } from "@/components/ui/git-chip"
import type { BranchInfo } from "@/lib/commit-branches"
import type { Commit, CommitMessageSegment } from "@/lib/commit-graph"
import type { LaneRow } from "@/lib/commit-lanes"
import { commitSubject, segmentsOf } from "@/lib/commit-message"
import { formatElapsed, formatInstant, formatRelative, toISO, type Instant } from "@/lib/time"
import { cn } from "@/lib/utils"

const numberFormats = new Map<string, Intl.NumberFormat>()

function formatCount(value: number, locale?: string) {
  let format = numberFormats.get(locale ?? "")
  if (!format) {
    format = new Intl.NumberFormat(locale)
    numberFormats.set(locale ?? "", format)
  }
  return format.format(value)
}

type CommitHistoryLabels = {
  /** The branch switcher's name. */
  branch: string
  /** The count beside the branch: "9 commits". */
  commits: (count: number, locale?: string) => string
  /** A pending commit's status, in place of its time. */
  pending: string
  copyHash: string
  copied: string
  /** "2 files" in a commit's details. */
  files: (count: number, locale?: string) => string
  /** Read out for `+18`. */
  additions: (count: number, locale?: string) => string
  /** Read out for `-9`. */
  deletions: (count: number, locale?: string) => string
  loadMore: string
  loading: string
  /** Names the select that shows one branch, or every one, in the branches view. */
  branchFilter: string
  /** Its first choice: every active branch. */
  allBranches: string
  /** Names the search field in the branch select, and is its placeholder. */
  searchBranches: string
  /** Shown in the branch select when no branch matches the search. */
  noBranches: string
  /** Read for a branch pill: "branch feature/webhooks". */
  branchHead: (name: string) => string
  /** Read for `↑3`: "3 ahead". */
  ahead: (count: number, locale?: string) => string
  /** Read for `↓12`: "12 behind". */
  behind: (count: number, locale?: string) => string
}

const commitHistoryLabels: CommitHistoryLabels = {
  branch: "Branch",
  commits: (count, locale) => `${formatCount(count, locale)} ${count === 1 ? "commit" : "commits"}`,
  pending: "Committing",
  copyHash: "Copy hash",
  copied: "Copied",
  files: (count, locale) => `${formatCount(count, locale)} ${count === 1 ? "file" : "files"}`,
  additions: (count, locale) => `${formatCount(count, locale)} ${count === 1 ? "addition" : "additions"}`,
  deletions: (count, locale) => `${formatCount(count, locale)} ${count === 1 ? "deletion" : "deletions"}`,
  loadMore: "Load more",
  loading: "Loading…",
  branchFilter: "Branches shown",
  allBranches: "All branches",
  searchBranches: "Search branches",
  noBranches: "No branches match",
  branchHead: (name) => `branch ${name}`,
  ahead: (count, locale) => `${formatCount(count, locale)} ahead`,
  behind: (count, locale) => `${formatCount(count, locale)} behind`,
}

const NONE: readonly BranchInfo[] = []

/** A branch at its head: a dot in its lane's colour, the name, and how far ahead and behind the base it is. */
// A press on it shows only this branch (the row's own press handler reads `data-branch`), so it's a pointer
// shortcut: keyboards and agents reach the same through the branch select and `focusBranch`.
function BranchPill({ branch, locale, focused }: { branch: BranchInfo; locale?: string; focused: boolean }) {
  return (
    <span
      data-slot="commit-branch-pill"
      data-state={branch.state}
      data-branch={branch.state === "base" ? undefined : branch.name}
      data-focused={focused ? "" : undefined}
      className="inline-flex max-w-48 min-w-0 items-center gap-inline rounded-sm bg-foreground/8 px-inline py-px font-mono text-caption leading-none text-muted-foreground data-branch:cursor-pointer data-branch:hover:bg-foreground/15 data-focused:ring-1 data-focused:ring-ring"
    >
      <span className={cn("size-1.5 shrink-0 rounded-full bg-current", laneColor(branch.tag))} />
      <span className="truncate text-foreground">{branch.name}</span>
      {branch.state !== "base" && <BranchCounts ahead={branch.ahead} behind={branch.behind} locale={locale} />}
    </span>
  )
}

type BranchCountsProps = {
  ahead: number
  behind: number
  locale?: string
  /** Says the counts in words for screen readers, where nothing around them already does. */
  spoken?: Pick<CommitHistoryLabels, "ahead" | "behind">
}

/**
 * How far a branch is ahead of and behind the base, as arrows and numbers. A zero side is left out, which reads
 * cleaner than a dimmed 0 and keeps every number shown at full contrast; the spoken text still says both.
 */
function BranchCounts({ ahead, behind, locale, spoken }: BranchCountsProps) {
  return (
    <span
      data-slot="commit-branch-counts"
      className="inline-flex shrink-0 items-center gap-inline text-caption text-muted-foreground tabular-nums"
    >
      <span aria-hidden="true" className="inline-flex items-center gap-inline [&_svg]:size-3 [&_svg]:shrink-0">
        {ahead > 0 && (
          <span className="inline-flex items-center">
            <ArrowUpIcon />
            {formatCount(ahead, locale)}
          </span>
        )}
        {behind > 0 && (
          <span className="inline-flex items-center">
            <ArrowDownIcon />
            {formatCount(behind, locale)}
          </span>
        )}
      </span>
      {spoken && <span className="sr-only">{`${spoken.ahead(ahead, locale)}, ${spoken.behind(behind, locale)}`}</span>}
    </span>
  )
}

type CommitRowContext = {
  now: Instant | undefined
  locale: string | undefined
  timeZone: string | undefined
  labels: CommitHistoryLabels
  copied: string | null
  copyHash: (id: string, event: Event) => void
  /** The branch the branches view is showing alone, if any. */
  focusedBranch?: string | null
}

type CommitRowProps = {
  commit: Commit
  index: number
  lanes: LaneRow
  depth: number
  /** A merge with nested commits: a chevron, and Left/Right open and close it. */
  merge: boolean
  detailsOpen: boolean
  /** Nested under a merge that was just expanded: the row eases in. */
  entering: boolean
  /** The merge that was just expanded: its new lane draws in. */
  drawIn: boolean
  /** The branches whose head this commit is, shown as pills in the branches view. */
  heads?: readonly BranchInfo[]
  context: CommitRowContext
  /** Where the row sits in the list's box while it's virtualized, in px. */
  top?: number
  measure?: (index: number, el: HTMLElement | null) => () => void
  /** Fills a piece of the subject, so find in page finds the row while it isn't rendered (`findableText`). */
  textSlot?: (index: number, el: HTMLElement | null, part: number) => () => void
}

function authorName(author: Commit["author"]) {
  if (author === undefined) return undefined
  return typeof author === "string" ? author : author.name
}

function hashOf(commit: Commit) {
  return commit.hash ?? commit.id.slice(0, 7)
}

type SegmentProps = { segment: CommitMessageSegment; textRef?: (el: HTMLElement | null) => () => void }

function MessageSegment({ segment, textRef }: SegmentProps) {
  switch (segment.type) {
    case "file":
      return <GitFileChip path={segment.path} textRef={textRef} />
    case "branch":
      return <GitBranchChip name={segment.name} textRef={textRef} />
    case "code":
      return (
        <code ref={textRef} className="rounded-sm bg-muted px-inline font-mono text-caption leading-tight">
          {textRef ? null : segment.text}
        </code>
      )
    default:
      return textRef ? <span ref={textRef} /> : segment.text
  }
}

type NameContext = Pick<CommitRowContext, "now" | "locale" | "labels">

/** What follows the subject in a row's name: ", 38 minutes ago, Release". */
/** What a branch pill reads: "branch feature/webhooks, 3 ahead, 12 behind". */
function branchName(branch: BranchInfo, context: NameContext) {
  const { labels, locale } = context
  const parts = [labels.branchHead(branch.name)]
  if (branch.state !== "base") parts.push(labels.ahead(branch.ahead, locale), labels.behind(branch.behind, locale))
  return parts.join(", ")
}

function commitNameSuffix(commit: Commit, context: NameContext, heads: readonly BranchInfo[] = NONE) {
  const when =
    commit.status === "pending"
      ? context.labels.pending
      : formatRelative(commit.date, { now: context.now, locale: context.locale })
  const parts = [
    when,
    ...(commit.tags ?? []).map((tag) => tag.label),
    ...heads.map((head) => branchName(head, context)),
  ]
  return parts.map((part) => `, ${part}`).join("")
}

/** A commit's accessible name: "Merge invoice-pdf into main, 38 minutes ago, Release". */
function commitName(commit: Commit, context: NameContext, heads?: readonly BranchInfo[]) {
  return commitSubject(commit) + commitNameSuffix(commit, context, heads)
}

function CommitDetails({ commit, context, id }: { commit: Commit; context: CommitRowContext; id: string }) {
  const { labels, locale, timeZone } = context
  const author = authorName(commit.author)
  const hash = hashOf(commit)
  const copied = context.copied === commit.id
  const { stats } = commit
  return (
    <div
      id={id}
      data-slot="commit-details"
      className="flex min-w-0 flex-col gap-inline pb-items text-caption text-muted-foreground"
    >
      <p className="flex flex-wrap items-center gap-inline">
        {author && <span className="font-medium text-foreground">{author}</span>}
        {author && <span aria-hidden="true">·</span>}
        <time dateTime={toISO(commit.date)}>{formatInstant(commit.date, { locale, timeZone })}</time>
      </p>
      <p className="flex flex-wrap items-center gap-inline">
        <span className="font-mono text-foreground">{hash}</span>
        <Button
          variant="ghost"
          size="icon"
          aria-label={copied ? labels.copied : labels.copyHash}
          // The history's copyHash action serves agents; this button would repeat it on every open row.
          data-agent-hidden=""
          className="size-6 text-muted-foreground [&_svg]:size-3.5"
          onClick={(event) => context.copyHash(commit.id, event.nativeEvent)}
          // The row's Enter toggles its details; on the button, Enter and Space press the button.
          onKeyDown={(event) => {
            if (event.key === "Enter" || event.key === " ") event.stopPropagation()
          }}
        >
          {copied ? <CheckIcon /> : <CopyIcon />}
        </Button>
        <output className="sr-only">{copied ? labels.copied : ""}</output>
        {stats && (
          <>
            <span aria-hidden="true">·</span>
            <span>{labels.files(stats.files, locale)}</span>
            <span className="font-mono text-success tabular-nums">
              <span aria-hidden="true">+{formatCount(stats.additions, locale)}</span>
              <span className="sr-only">{labels.additions(stats.additions, locale)}</span>
            </span>
            <span className="font-mono text-destructive tabular-nums">
              <span aria-hidden="true">-{formatCount(stats.deletions, locale)}</span>
              <span className="sr-only">{labels.deletions(stats.deletions, locale)}</span>
            </span>
          </>
        )}
      </p>
      {commit.body && <p className="text-body-sm whitespace-pre-line">{commit.body}</p>}
    </div>
  )
}

/** Keeps the details mounted while they close, so their height can animate to 0 before they leave. */
function useClosing(open: boolean) {
  const [wasOpen, setWasOpen] = useState(open)
  const [closing, setClosing] = useState(false)
  if (wasOpen !== open) {
    setWasOpen(open)
    setClosing(!open)
  }
  return { mounted: open || closing, done: () => setClosing(false) }
}

/** Whether a pending commit just finished, so its node, time and tags ease in once. */
function useFinished(status: Commit["status"]) {
  const [previous, setPrevious] = useState(status)
  const [finished, setFinished] = useState(false)
  if (previous !== status) {
    setPrevious(status)
    setFinished(previous === "pending")
  }
  return finished
}

const easeIn = "transition duration-panel ease-standard starting:opacity-0"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- text starts past the lanes of the row's first line, each --commit-lane wide
const lineIndent = "ps-[calc(var(--commit-lane)*var(--indent)+var(--gap-inline))]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- the details start past every lane that runs on below the line
const detailsIndent = "ps-[calc(var(--commit-lane)*var(--indent-below)+var(--gap-inline))]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- the details' height animates as a grid row, 0fr to 1fr
const detailsRows = "grid-rows-[0fr] data-open:grid-rows-[1fr] data-open:starting:grid-rows-[0fr]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- grid-template-rows isn't in the transition utilities
const detailsTransition = "transition-[grid-template-rows]"

const CommitRow = memo(function CommitRow({
  commit,
  index,
  lanes,
  depth,
  merge,
  detailsOpen,
  entering,
  drawIn,
  context,
  top,
  measure,
  textSlot,
  heads,
}: CommitRowProps) {
  const details = useClosing(detailsOpen)
  const finished = useFinished(commit.status)
  const pending = commit.status === "pending"
  const { labels, now, locale, timeZone } = context
  const node: CommitNodeKind = pending ? "pending" : depth > 0 || lanes.tag !== 0 ? "branch" : "commit"
  const columns = graphColumns(lanes)
  const more = columns > lanes.width
  const below = more ? columns : Math.max(lanes.width, ...lanes.out.map((lane) => lane + 1))
  const indent = more ? columns : Math.max(lanes.lane, ...lanes.through, ...lanes.into) + 1
  const style = { "--indent": indent, "--indent-below": below } as CSSProperties
  const detailsId = `commit-details-${commit.id}`
  const tags = commit.tags ?? []
  const subtle = finished ? easeIn : undefined

  let when: ReactNode
  if (pending) when = <span className="text-caption font-medium text-link">{labels.pending}</span>
  else
    when = (
      <time
        dateTime={toISO(commit.date)}
        title={formatInstant(commit.date, { locale, timeZone })}
        className={cn("text-caption text-muted-foreground tabular-nums", subtle)}
        suppressHydrationWarning
      >
        {formatElapsed(commit.date, { now, locale })}
      </time>
    )

  return (
    <TreeItem
      value={commit.id}
      label={commitSubject(commit)}
      ref={measure ? (el: HTMLElement | null) => measure(index, el) : undefined}
      data-index={index}
      style={top === undefined ? style : { ...style, top }}
      data-pending={pending ? "" : undefined}
      data-details-open={detailsOpen ? "" : undefined}
      data-entering={entering ? "" : undefined}
      aria-describedby={detailsOpen ? detailsId : undefined}
      className={cn(
        "group/commit flex flex-col outline-none",
        top === undefined ? "relative" : "absolute inset-x-0",
        // Focus mode: every row but the open, hovered or focused one reads quieter, still at 4.5:1.
        "group-data-focus-mode/history:not-data-details-open:not-hover:not-focus-within:text-muted-foreground",
        entering && "transition duration-panel ease-standard starting:-translate-y-1 starting:opacity-0",
      )}
      render={(props) => <div {...props} data-slot="commit-row" />}
    >
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 h-(--commit-line) rounded-control transition-colors duration-micro ease-standard group-hover/commit:bg-accent group-focus-visible/commit:bg-accent group-focus-visible/commit:ring-2 group-focus-visible/commit:ring-ring group-data-details-open/commit:bg-accent"
      />
      <CommitGraphCell row={lanes} node={node} finished={finished} drawIn={drawIn} />
      <TreeItemLabel
        className={cn(
          "relative flex h-(--commit-line) min-w-0 items-center gap-items pe-(--item-padding-x) text-body-sm",
          lineIndent,
        )}
      >
        <span data-slot="commit-message" className="flex min-w-0 items-center gap-inline">
          <span
            className={cn(
              "truncate",
              depth > 0 && "text-muted-foreground group-data-details-open/commit:text-foreground",
            )}
          >
            {segmentsOf(commit).map((segment, at) => (
              <MessageSegment
                // oxlint-disable-next-line react/no-array-index-key -- segments have no identity beyond their place
                key={at}
                segment={segment}
                textRef={textSlot ? (el) => textSlot(index, el, at) : undefined}
              />
            ))}
          </span>
          {merge && (
            <TreeItemIndicator className="inline-flex shrink-0 text-muted-foreground transition-transform duration-micro ease-standard data-expanded:rotate-90 rtl:-scale-x-100 [&_svg]:size-3.5">
              <ChevronRightIcon />
            </TreeItemIndicator>
          )}
        </span>
        <span className="sr-only">{commitNameSuffix(commit, context, heads)}</span>
        <span aria-hidden="true" className="ms-auto flex shrink-0 items-center gap-items">
          {heads?.map((head) => (
            <BranchPill
              key={head.name}
              branch={head}
              locale={context.locale}
              focused={context.focusedBranch === head.name}
            />
          ))}
          {tags.map((tag) => (
            <Badge
              key={tag.label}
              tone={tag.tone ?? "neutral"}
              className={cn("rounded-sm border-transparent py-0 leading-tight", subtle)}
            >
              {tag.label}
            </Badge>
          ))}
          {when}
        </span>
      </TreeItemLabel>
      {details.mounted && (
        <div
          data-slot="commit-details-panel"
          data-open={detailsOpen ? "" : undefined}
          className={cn(
            "grid pe-(--item-padding-x) duration-panel ease-standard",
            detailsRows,
            detailsTransition,
            detailsIndent,
          )}
          onTransitionEnd={(event) => {
            if (event.target !== event.currentTarget) return
            if (!detailsOpen) {
              details.done()
              return
            }
            // Details opened at the bottom edge would end below the fold; only a row someone is on scrolls.
            const row = event.currentTarget.closest<HTMLElement>("[data-slot=commit-row]")
            if (row?.contains(document.activeElement)) row.scrollIntoView({ block: "nearest" })
          }}
        >
          <div className="min-h-0 overflow-hidden">
            <CommitDetails commit={commit} context={context} id={detailsId} />
          </div>
        </div>
      )}
    </TreeItem>
  )
})

export { BranchCounts, BranchPill, branchName, CommitRow, commitHistoryLabels, commitName, hashOf }
export type { CommitHistoryLabels, CommitRowContext, CommitRowProps }

import {
  createChange,
  createController,
  definePrimitive,
  dispatch,
  type ChangeDetails,
  type ChangeOptions,
} from "@ui-sdk/core"

type CommitHistoryChangeReason = "item-press" | "trigger-press" | "list-navigation" | "imperative"

type CommitLookupEntry = { id: string; hash: string; subject: string; merge: boolean }

/** How the primitive finds commits without holding a copy of a long history. */
type CommitLookup = {
  /** A commit by id, hash (or a prefix of 4 or more characters) or exact subject. */
  find: (ref: string) => CommitLookupEntry | undefined
  /** Every commit as agents list them: the id and the row's accessible name. Built on demand. */
  entries: () => readonly { value: string; label: string }[]
  /** The branches beside the base, as `listBranches` gives them. */
  branches?: () => readonly CommitBranchSummary[]
}

/** A branch as agents read it: where its head is and how far it is from the base. */
type CommitBranchSummary = {
  name: string
  head: string
  ahead: number
  behind: number
  updatedAt: string | undefined
  state: "base" | "active" | "merged" | "stale"
}

type CommitHistoryOptions = {
  lookup?: CommitLookup
  /** Open merges, by id. */
  expanded?: readonly string[]
  defaultExpanded?: readonly string[]
  onExpandedChange?: (expanded: string[], details: ChangeDetails<CommitHistoryChangeReason>) => void
  /** Commits whose details show under their row. */
  details?: readonly string[]
  defaultDetails?: readonly string[]
  onDetailsChange?: (open: string[], details: ChangeDetails<CommitHistoryChangeReason>) => void
  /** `"single"` (default) closes the open details when others open. */
  detailsMode?: "single" | "multiple"
  branch?: string
  branches?: readonly string[]
  onBranchChange?: (branch: string, details: ChangeDetails<CommitHistoryChangeReason>) => void
  onOpenCommit?: (id: string, details: ChangeDetails<CommitHistoryChangeReason>) => void
  onCopyHash?: (hash: string, details: ChangeDetails<"copy"> & { id: string }) => void
  /** The branch in focus in the branches view: its head scrolled to and focused, and filtered to with `filterBranch`. */
  focusedBranch?: string | null
  onFocusedBranchChange?: (branch: string | null, details: ChangeDetails<CommitHistoryChangeReason>) => void
  controller?: CommitHistoryController
}

interface CommitHistoryController {
  expand: (ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) => boolean | undefined
  collapse: (ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) => boolean | undefined
  expandDetails: (ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) => boolean | undefined
  collapseDetails: (ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) => boolean | undefined
  openCommit: (ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) => boolean | undefined
  selectBranch: (name: string, options?: ChangeOptions<CommitHistoryChangeReason>) => boolean | undefined
  focusBranch: (name: string | null, options?: ChangeOptions<CommitHistoryChangeReason>) => boolean | undefined
}

const COPIED_FOR = 2000

function reasonOf(options: unknown): { reason: CommitHistoryChangeReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<CommitHistoryChangeReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

const list = (value: readonly string[] | undefined) => (value ? [...value] : undefined)

const commitHistory = definePrimitive({
  name: "commit-history",
  options: {
    lookup: "value",
    expanded: "list",
    defaultExpanded: "list",
    onExpandedChange: "callback",
    details: "list",
    defaultDetails: "list",
    onDetailsChange: "callback",
    detailsMode: "string",
    branch: "string",
    branches: "list",
    onBranchChange: "callback",
    onOpenCommit: "callback",
    onCopyHash: "callback",
    focusedBranch: "value",
    onFocusedBranchChange: "callback",
    controller: "value",
  },
  state: (options: CommitHistoryOptions) => ({
    expanded: list(options.expanded ?? options.defaultExpanded) ?? [],
    details: list(options.details ?? options.defaultDetails) ?? [],
    branch: options.branch ?? null,
    focusedBranch: options.focusedBranch ?? null,
    copied: null as string | null,
  }),
  sync: (options) => ({
    ...(options.expanded === undefined ? {} : { expanded: [...options.expanded] }),
    ...(options.details === undefined ? {} : { details: [...options.details] }),
    ...(options.branch === undefined ? {} : { branch: options.branch }),
    ...(options.focusedBranch === undefined ? {} : { focusedBranch: options.focusedBranch }),
  }),
  controlled: ["expanded", "details", "branch", "focusedBranch"],
  api: (context) => {
    const change = createChange(context)
    let timer: ReturnType<typeof setTimeout> | undefined
    context.onDestroy(() => clearTimeout(timer))

    // The agent bridge passes arguments unchecked.
    const find = (ref: unknown) => {
      const entry = typeof ref === "string" ? context.options().lookup?.find(ref) : undefined
      if (!entry) throw new RangeError(`No commit "${String(ref)}". Pass a commit's id, hash or subject.`)
      return entry
    }
    const findMerge = (ref: unknown, action: string) => {
      const entry = find(ref)
      if (!entry.merge) throw new RangeError(`"${entry.subject}" has no merged commits to ${action}.`)
      return entry
    }
    const setExpanded = (next: string[], options?: unknown) => change("expanded", next, reasonOf(options))
    const setDetails = (next: string[], options?: unknown) => change("details", next, reasonOf(options))

    const api = {
      setExpanded(expanded: readonly string[], options?: ChangeOptions<CommitHistoryChangeReason>) {
        return setExpanded([...expanded], options)
      },
      expand(ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) {
        const { id } = findMerge(ref, "expand")
        const { expanded } = context.store.get()
        return expanded.includes(id) ? true : setExpanded([...expanded, id], options)
      },
      collapse(ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) {
        const { id } = findMerge(ref, "collapse")
        const { expanded } = context.store.get()
        return expanded.includes(id)
          ? setExpanded(
              expanded.filter((open) => open !== id),
              options,
            )
          : true
      },
      expandDetails(ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) {
        const { id } = find(ref)
        const { details } = context.store.get()
        if (details.includes(id)) return true
        return setDetails(context.options().detailsMode === "multiple" ? [...details, id] : [id], options)
      },
      collapseDetails(ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) {
        const { id } = find(ref)
        const { details } = context.store.get()
        return details.includes(id)
          ? setDetails(
              details.filter((open) => open !== id),
              options,
            )
          : true
      },
      toggleDetails(ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) {
        const { id } = find(ref)
        return context.store.get().details.includes(id)
          ? api.collapseDetails(id, options)
          : api.expandDetails(id, options)
      },
      toggle(ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) {
        const { id } = findMerge(ref, "expand")
        return context.store.get().expanded.includes(id) ? api.collapse(id, options) : api.expand(id, options)
      },
      openCommit(ref: string, options?: ChangeOptions<CommitHistoryChangeReason>) {
        const { id } = find(ref)
        if (!context.options().onOpenCommit) throw new Error("This history doesn't open commits; use expandDetails.")
        return !dispatch(context, "onOpenCommit", id, reasonOf(options))
      },
      /** Copies the commit's hash where the page has clipboard access, and returns it either way. */
      async copyHash(ref: string, event?: Event) {
        const { id, hash } = find(ref)
        const clipboard = typeof navigator === "undefined" ? undefined : navigator.clipboard
        let copied = false
        if (clipboard) {
          try {
            await clipboard.writeText(hash)
            copied = true
          } catch {
            copied = false
          }
        }
        if (copied) {
          clearTimeout(timer)
          context.store.set({ copied: id })
          timer = setTimeout(() => context.store.set({ copied: null }), COPIED_FOR)
          dispatch(context, "onCopyHash", hash, { reason: "copy", event, id })
        }
        return hash
      },
      selectBranch(name: string, options?: ChangeOptions<CommitHistoryChangeReason>) {
        const { branches = [], onBranchChange } = context.options()
        if (!onBranchChange) throw new Error("This history shows one branch.")
        if (typeof name !== "string" || !branches.includes(name)) {
          throw new RangeError(`No branch "${String(name)}". Branches: ${branches.join(", ")}.`)
        }
        return change("branch", name, reasonOf(options))
      },
      /** Scrolls to a branch's head and focuses it, in the branches view; `null` lets go of it. */
      focusBranch(name: string | null, options?: ChangeOptions<CommitHistoryChangeReason>) {
        const branches = context.options().lookup?.branches?.() ?? []
        if (name !== null && !branches.some((branch) => branch.name === name)) {
          const names = branches.map((branch) => branch.name).join(", ") || "none"
          throw new RangeError(`No branch "${String(name)}" in the overview. Branches: ${names}.`)
        }
        return change("focusedBranch", name, reasonOf(options))
      },
      /** The branches beside the base with their heads and how far ahead and behind they are. Reads only. */
      listBranches() {
        return [...(context.options().lookup?.branches?.() ?? [])]
      },
      commits: () => context.options().lookup?.entries() ?? [],
    }
    return api
  },
  slots: (slot) => ({
    root: slot({
      role: "region",
      attrs: (state) => ({
        "data-details-open": state.details.length > 0 ? "" : undefined,
        "data-branch": state.branch ?? undefined,
      }),
    }),
  }),
  agent: {
    actions: [
      "expandDetails",
      "collapseDetails",
      "expand",
      "collapse",
      "copyHash",
      "openCommit",
      "selectBranch",
      "focusBranch",
      "listBranches",
    ],
    items: (api) => api.commits(),
  },
})

function createCommitHistoryController() {
  return createController<CommitHistoryController>()
}

export { commitHistory, createCommitHistoryController }
export type {
  CommitBranchSummary,
  CommitHistoryChangeReason,
  CommitHistoryController,
  CommitHistoryOptions,
  CommitLookup,
  CommitLookupEntry,
}

import { CheckIcon } from "lucide-react"
import { memo, type CSSProperties } from "react"

import type { LaneRow } from "@/lib/commit-lanes"
import { cn } from "@/lib/utils"

type CommitNodeKind = "commit" | "branch" | "pending"

type CommitGraphCellProps = {
  row: LaneRow
  node: CommitNodeKind
  /** The node just stopped being pending: it grows into its check. */
  finished?: boolean
  /** Lanes that opened because their merge was just expanded draw in. */
  drawIn?: boolean
}

// Curves are drawn in a lane 14 units wide and a line 30 units tall, the default theme's sizes, and stretch to
// the theme's. Straight runs are boxes rather than SVG: Chrome doesn't repaint a stretched SVG's
// non-scaling strokes when the row resizes, which left gaps between rows.
const LANE = 14
const LINE = 30
const x = (lane: number) => (lane + 0.5) * LANE

const MID = LINE / 2

function intoCurve(from: number, node: number) {
  const [a, b] = [String(x(from)), String(x(node))]
  return `M${a} 0C${a} ${String(MID * 0.6)} ${b} ${String(MID * 0.4)} ${b} ${String(MID)}`
}

function outCurve(node: number, to: number) {
  const [a, b] = [String(x(node)), String(x(to))]
  return `M${a} ${String(MID)}C${a} ${String(MID * 1.6)} ${b} ${String(MID * 1.4)} ${b} ${String(LINE)}`
}

type Run = { lane: number; from: "top" | "middle" | "line"; to: "middle" | "bottom"; tag: number }

const runFrom = { top: "top-0", middle: "top-[calc(var(--commit-line)/2)]", line: "top-(--commit-line)" }
const runTo = { middle: "bottom-[calc(100%-var(--commit-line)/2)]", bottom: "bottom-0" }

function runsOf({ lane, into, out, through, tagsTop, tagsBottom }: LaneRow): Run[] {
  const runs: Run[] = through.map((at) => ({ lane: at, from: "top", to: "bottom", tag: tagsTop[at] ?? 0 }))
  if (into.includes(lane)) runs.push({ lane, from: "top", to: "middle", tag: tagsTop[lane] ?? 0 })
  for (const to of out) {
    const tag = tagsBottom[to] ?? 0
    runs.push(to === lane ? { lane, from: "middle", to: "bottom", tag } : { lane: to, from: "line", to: "bottom", tag })
  }
  return runs
}

// A lane's colour by its tag: the link blue for the base or a lone trail, the categorical chart colours for
// branches, a tone when a branch asks for one. Never the only cue: branch lanes carry a pill with the name.
const laneColors: Record<number, string> = {
  0: "text-link",
  1: "text-chart-1",
  2: "text-chart-2",
  3: "text-chart-3",
  4: "text-chart-4",
  5: "text-chart-5",
  10: "text-muted-foreground",
  11: "text-info",
  12: "text-success",
  13: "text-warning",
  14: "text-destructive",
  15: "text-violet",
}

function laneColor(tag: number) {
  return laneColors[tag] ?? "text-link"
}

const drawInClassName = "transition-opacity duration-panel ease-standard starting:opacity-0"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- a 1.5px stroke matches the lane boxes beside the curves
const curveClassName = "fill-none stroke-current stroke-[1.5]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- the graph is as wide as its lanes, each --commit-lane wide
const graphClassName = "w-[calc(var(--commit-lane)*var(--lanes))]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- a 1.5px run centred on its lane, like the curves' stroke
const runClassName = "start-[calc(var(--commit-lane)*(var(--at)+0.5)-0.75px)] w-[1.5px]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- the node sits in its lane's cell
const nodeCellClassName = "start-[calc(var(--commit-lane)*var(--lane))]"
// oxlint-disable-next-line shadcn/no-arbitrary-values -- the "+N" of lanes not drawn takes the columns after the last drawn lane
const moreClassName = "start-[calc(var(--commit-lane)*var(--drawn))] w-[calc(var(--commit-lane)*2)]"

const nodeClassNames: Record<CommitNodeKind, string> = {
  commit: "size-3.5 bg-info-soft outline-2 outline-card",
  branch: "size-1.5 bg-current outline-2 outline-card",
  pending:
    "size-3 border-[1.5px] border-current border-e-transparent bg-card animate-spin motion-reduce:animate-none motion-reduce:border-e-current",
}

/** The columns a row's graph takes: its lanes, and two more for "+N" when some aren't drawn. */
function graphColumns(row: LaneRow) {
  return row.width + (row.hidden > 0 || row.nodeHidden ? 2 : 0)
}

/**
 * One row of the graph: lanes passing by, edges into and out of the row's node, and the lanes that run on below
 * its first line, through its open details. Lanes past the row's cap show as "+N". It is decorative: the row's
 * name says what the graph shows.
 */
const CommitGraphCell = memo(function CommitGraphCell({ row, node, finished, drawIn }: CommitGraphCellProps) {
  const { lane, width, into, out, tagsTop, tagsBottom, hidden, nodeHidden } = row
  const curvesIn = into.filter((from) => from !== lane)
  const curvesOut = out.filter((to) => to !== lane)
  const more = hidden > 0 || nodeHidden
  const style = { "--lanes": graphColumns(row), "--lane": nodeHidden ? width : lane, "--drawn": width } as CSSProperties
  return (
    <span
      aria-hidden="true"
      data-slot="commit-graph"
      style={style}
      className={cn("pointer-events-none absolute inset-y-0 start-0", graphClassName)}
    >
      {runsOf(row).map((run) => (
        <span
          key={`${String(run.lane)}${run.from}`}
          data-slot="commit-lane"
          data-tag={run.tag}
          style={{ "--at": run.lane } as CSSProperties}
          className={cn(
            "absolute bg-current",
            laneColor(run.tag),
            runClassName,
            runFrom[run.from],
            runTo[run.to],
            run.from === "line" && drawIn && drawInClassName,
          )}
        />
      ))}
      {(curvesIn.length > 0 || curvesOut.length > 0) && (
        // oxlint-disable-next-line eskais/no-inline-icons -- the commit graph's curves, not an icon
        <svg
          viewBox={`0 0 ${String(graphColumns(row) * LANE)} ${String(LINE)}`}
          preserveAspectRatio="none"
          className="absolute inset-x-0 top-0 h-(--commit-line) w-full overflow-visible rtl:-scale-x-100"
        >
          {curvesIn.map((from) => (
            <path
              key={`i${String(from)}`}
              d={intoCurve(from, lane)}
              className={cn(curveClassName, laneColor(tagsTop[from] ?? 0))}
            />
          ))}
          {curvesOut.map((to) => (
            <path
              key={`o${String(to)}`}
              d={outCurve(lane, to)}
              className={cn(curveClassName, laneColor(tagsBottom[to] ?? 0), drawIn && drawInClassName)}
            />
          ))}
        </svg>
      )}
      {more && (
        <span
          data-slot="commit-graph-more"
          className={cn(
            "absolute top-0 flex h-(--commit-line) items-center justify-end font-mono text-caption text-muted-foreground tabular-nums",
            moreClassName,
          )}
        >
          +{hidden}
        </span>
      )}
      <span
        className={cn(
          "absolute top-0 flex h-(--commit-line) w-(--commit-lane) items-center justify-center",
          nodeCellClassName,
          laneColor(row.tag),
        )}
      >
        <span
          data-slot="commit-node"
          data-node={node}
          className={cn(
            "inline-flex shrink-0 items-center justify-center rounded-full",
            nodeClassNames[node],
            finished && "transition duration-panel ease-standard starting:scale-50 starting:opacity-0",
          )}
        >
          {node === "commit" && <CheckIcon className="size-2.5" strokeWidth={3} />}
        </span>
      </span>
    </span>
  )
})

export { CommitGraphCell, graphColumns, laneColor }
export type { CommitGraphCellProps, CommitNodeKind }

import { useCallback, useEffect, useEffectEvent, useMemo, useState } from "react"

import { updateCommitGraph, visibleRows, type Commit, type CommitGraph } from "@/lib/commit-graph"
import {
  createBranchModel,
  headTagOf,
  type BranchModel,
  type BranchModelOptions,
  type CommitBranch,
} from "@/lib/commit-branches"
import { createLaneLayout } from "@/lib/commit-lanes"

/**
 * The trail's structure, carried over from the previous render so an appended page costs only its own rows. It
 * is derived during render from the last commits seen, the pattern React documents for state from props.
 */
function useCommitGraph(commits: readonly Commit[]): CommitGraph {
  const [cache, setCache] = useState<{ commits: readonly Commit[]; graph: CommitGraph } | null>(null)
  if (cache?.commits === commits) return cache.graph
  const graph = updateCommitGraph(cache?.graph, commits)
  setCache({ commits, graph })
  return graph
}

/** The merges opened since the last render, whose rows ease in and whose lanes draw in. */
function useJustExpanded(expanded: readonly string[]): ReadonlySet<string> {
  const [seen, setSeen] = useState({ expanded, added: new Set<string>() as ReadonlySet<string> })
  if (seen.expanded === expanded) return seen.added
  const before = new Set(seen.expanded)
  const added = new Set(expanded.filter((id) => !before.has(id)))
  setSeen({ expanded, added })
  return added
}

type TrailOptions = {
  maxLanes?: number
  /** The branches view: the base keeps lane 0 and each branch's lane takes its colour. */
  model?: BranchModel
  /** With a model, shows only the base and this branch's commits (its index in `model.active`). */
  only?: number
}

function useCommitTrail(graph: CommitGraph, expanded: readonly string[], options: TrailOptions = {}) {
  const { maxLanes, model, only } = options
  const open = useMemo(() => new Set(expanded), [expanded])
  const visible = useMemo(() => {
    const owner = model?.owner
    const skip =
      owner && only !== undefined ? (row: number) => (owner[row] ?? -1) >= 0 && owner[row] !== only : undefined
    return visibleRows(graph, open, skip)
  }, [graph, open, model, only])
  const layout = useMemo(
    () =>
      createLaneLayout(graph, visible, {
        maxLanes,
        reserve: model?.base ? [{ id: model.base.head, tag: 0 }] : undefined,
        headTag: model ? headTagOf(model) : undefined,
        keepLanes: model !== undefined,
      }),
    [graph, visible, maxLanes, model],
  )
  return { graph, open, visible, layout }
}

/** The branches view's model, worked out once per graph and branch list. */
function useBranchModel(
  graph: CommitGraph,
  branches: readonly CommitBranch[] | undefined,
  options: BranchModelOptions,
) {
  const { base, staleAfter, now } = options
  return useMemo(
    () => (branches && branches.length > 0 ? createBranchModel(graph, branches, { base, staleAfter, now }) : undefined),
    [graph, branches, base, staleAfter, now],
  )
}

/**
 * Brings a branch's head into view and focuses it when the branch comes into focus, from the select, a pill or an
 * agent: the row may not be rendered until the list scrolls to it, so focus waits a frame for it.
 */
function useFocusHead(
  head: { id: string; position: number } | undefined,
  reveal: (position: number) => void,
  focus: (id: string) => void,
) {
  const id = head?.id
  const position = head?.position
  const revealRow = useEffectEvent(reveal)
  const focusRow = useEffectEvent(focus)
  useEffect(() => {
    if (id === undefined || position === undefined || position < 0) return undefined
    revealRow(position)
    const frame = requestAnimationFrame(() => focusRow(id))
    return () => cancelAnimationFrame(frame)
  }, [id, position])
}

/** A ref for a sentinel after the last row: `onReach` runs when it comes within 200px of the viewport. */
function useReachEnd(onReach: (() => unknown) | undefined, enabled: boolean) {
  return useCallback(
    (node: HTMLElement | null) => {
      if (!node || !enabled || !onReach || typeof IntersectionObserver === "undefined") return undefined
      const observer = new IntersectionObserver(
        (entries) => {
          if (entries.some((entry) => entry.isIntersecting)) void onReach()
        },
        { rootMargin: "200px 0px" },
      )
      observer.observe(node)
      return () => observer.disconnect()
    },
    [onReach, enabled],
  )
}

export { useBranchModel, useCommitGraph, useCommitTrail, useFocusHead, useJustExpanded, useReachEnd }

import type { PrimitiveInstance } from "@ui-sdk/core"
import { useSyncExternalStore } from "react"

/** A primitive instance's state, re-rendering the component that reads it on every change. */
function useInstanceState<State>(instance: PrimitiveInstance): State {
  return useSyncExternalStore(instance.subscribe, instance.get, instance.get) as State
}

export { useInstanceState }

import { useCallback } from "react"

import { useFindableRows } from "@/components/ui/use-findable-rows"
import { useVirtualRows } from "@/components/ui/virtual-rows"

type TrailRowsOptions = {
  count: number
  /** A row's estimated height in px before it is measured. */
  estimate: number
  getKey: (index: number) => string
  /** A row's text for find in page, in the pieces its `textSlot` elements hold. */
  text: (index: number) => string | readonly string[]
  /** Find in page reaches rows that aren't rendered, through UI SDK's virtualizer and findable layers. */
  findable: boolean
}

/** A rendered row, at `top` px in an absolutely positioned box, or in flow; or the space of rows not rendered. */
type TrailSegment = { type: "row"; index: number; top?: number } | { type: "gap"; size: number; key: string }

const noop = () => {}

/**
 * The rows of a long trail or tree. By default `virtual-rows`, rows in document flow; with `findable`, UI SDK's
 * virtualizer with absolutely positioned rows, whose findable layers let find in page reach the rows that aren't
 * rendered, at a cost `tooling/git-bench.mjs` measures. Only one of them ever holds rows.
 */
function useTrailRows({ count, estimate, getKey, text, findable }: TrailRowsOptions) {
  const flow = useVirtualRows({ count: findable ? 0 : count, estimateSize: estimate, getKey })
  const { setScroller, ...layered } = useFindableRows({
    count: findable ? count : 0,
    estimate,
    getKey,
    text,
    findable,
  })
  const absolute = findable && layered.enabled

  let segments: TrailSegment[]
  if (absolute) segments = layered.items.map((item) => ({ type: "row", index: item.index, top: item.start }))
  else if (findable) segments = Array.from({ length: count }, (_, index) => ({ type: "row", index }))
  else
    segments = flow.segments.map((segment) =>
      segment.type === "row" ? { type: "row", index: segment.index } : segment,
    )

  // Rows are memoized: everything they get keeps its identity across scrolls.
  const { measureElement } = flow
  const { measure: measureLayered } = layered
  const measure = useCallback(
    (index: number, el: HTMLElement | null) => {
      if (absolute) return measureLayered(index, el)
      return measureElement?.(el) ?? noop
    },
    [absolute, measureLayered, measureElement],
  )
  const { pin: pinFlow, scrollToIndex: scrollFlow } = flow
  const { pin: pinLayered, scrollToIndex: scrollLayered } = layered
  const pin = useCallback(
    (index: number | undefined) => (absolute ? pinLayered(index) : pinFlow(index)),
    [absolute, pinFlow, pinLayered],
  )
  const { renderNow } = flow
  /** Renders a row wherever the list is scrolled and scrolls to it, like a branch's head about to take focus. */
  const reveal = useCallback(
    (index: number) => {
      if (absolute) {
        scrollLayered(index)
        return
      }
      renderNow(index)
      scrollFlow(index)
    },
    [absolute, renderNow, scrollFlow, scrollLayered],
  )
  const scrollToIndex = useCallback(
    (index: number) => (absolute ? scrollLayered(index) : scrollFlow(index)),
    [absolute, scrollFlow, scrollLayered],
  )

  return {
    /** Rows render only in view, by either engine. */
    virtual: absolute || flow.enabled,
    /** The rows' box is `height` px tall and rows sit at their `top`. */
    absolute,
    height: absolute ? layered.size : undefined,
    segments,
    /** Pass as the `ref` of the element the rows are in, in flow. */
    anchor: flow.anchor,
    /** Pass as the `ref` of the scroller, for UI SDK's virtualizer. */
    setScroller,
    measure: absolute || flow.enabled ? measure : undefined,
    textSlot: absolute ? layered.findableText : undefined,
    pin,
    scrollToIndex,
    reveal,
  }
}

export { useTrailRows }
export type { TrailRowsOptions, TrailSegment }

import { createVirtualizer } from "@ui-sdk/core"
import { useCallback, useEffect, useLayoutEffect, useState, useSyncExternalStore } from "react"

/** Past this many rows only the rows in view render. */
const FINDABLE_ROWS_THRESHOLD = 200

type FindableRowsOptions = {
  count: number
  /** A row's estimated height in px before it is measured. */
  estimate: number
  getKey: (index: number) => string
  /** The text find in page should find in a row: what it shows, in the pieces its `findableText` elements hold. */
  text: (index: number) => string | readonly string[]
  /** Keeps rows that aren't rendered findable, through UI SDK's findable layers, built once the page is idle. */
  findable: boolean
}

type Latest = Omit<FindableRowsOptions, "findable">

const noKeep: readonly number[] = []

// The layers hold a stand-in for every row, so they wait until the first paint is done and the page is idle.
function whenIdle(run: () => void) {
  const idle = globalThis.requestIdleCallback as typeof requestIdleCallback | undefined
  const cancelIdle = globalThis.cancelIdleCallback as typeof cancelIdleCallback | undefined
  if (idle && cancelIdle) {
    const handle = idle(run, { timeout: 2000 })
    return () => cancelIdle(handle)
  }
  const timer = setTimeout(run, 200)
  return () => clearTimeout(timer)
}

/** A virtualizer that reads the newest options, which `update` swaps in; outside React, so it can hold them. */
function createRows(initial: Latest) {
  let latest = initial
  let keep = noKeep
  const virtual = createVirtualizer({
    count: () => latest.count,
    estimate: () => latest.estimate,
    key: (index) => latest.getKey(index),
    overscan: 8,
    keep: () => keep,
    findable: (index) => latest.text(index),
  })
  return {
    virtual,
    update(next: Latest) {
      const same =
        latest.count === next.count &&
        latest.getKey === next.getKey &&
        latest.text === next.text &&
        latest.estimate === next.estimate
      if (same) return
      latest = next
      virtual.refresh()
    },
    // Read on the virtualizer's next update, like the scroll a key press makes: refreshing here would render the
    // list on every focus move.
    pin(index: number | undefined) {
      if (keep[0] !== index) keep = index === undefined ? noKeep : [index]
    },
  }
}

/**
 * Rows on UI SDK's virtualizer: past 200 rows, only those in view render, absolutely positioned in a box as tall as
 * every row and measured as they render, so their heights can change. With `findable`, find in page reaches the
 * rows that aren't rendered and scrolls to the one it matched. Give the scroller a bounded height.
 */
function useFindableRows({ count, estimate, getKey, text, findable }: FindableRowsOptions) {
  const enabled = count > FINDABLE_ROWS_THRESHOLD
  const [rows] = useState(() => createRows({ count, estimate, getKey, text }))
  const { virtual } = rows
  const [scroller, setScroller] = useState<HTMLElement | null>(null)

  // The virtualizer reads the newest options when it computes; `update` tells it only when they changed.
  useLayoutEffect(() => {
    rows.update({ count, estimate, getKey, text })
  })

  useEffect(() => {
    if (!scroller || !enabled) return undefined
    let disconnect = virtual.connect(scroller)
    if (!findable) return () => disconnect()
    const cancel = whenIdle(() => {
      disconnect()
      disconnect = virtual.connect(scroller, { findable: true })
    })
    return () => {
      cancel()
      disconnect()
    }
  }, [virtual, scroller, enabled, findable])

  const items = useSyncExternalStore(virtual.subscribe, virtual.items, virtual.items)
  const size = useSyncExternalStore(virtual.subscribe, virtual.size, virtual.size)

  /** Keeps a row rendered wherever the list scrolls, like the one with focus. */
  const pin = useCallback((index: number | undefined) => rows.pin(index), [rows])
  const scrollToIndex = useCallback(
    (index: number) => {
      if (enabled) virtual.scrollToIndex(index)
    },
    [virtual, enabled],
  )

  return {
    enabled,
    items,
    size,
    /** The scroller, the nearest element that scrolls the rows: pass it as its `ref`. */
    setScroller,
    measure: virtual.measure,
    findableText: virtual.findableText,
    pin,
    scrollToIndex,
  }
}

export { FINDABLE_ROWS_THRESHOLD, useFindableRows }
export type { FindableRowsOptions }

"use client"

import type { TreeItemData } from "@ui-sdk/react/tree"

import type { CommitBranchSummary } from "@/components/ui/commit-history-primitive"
import { CommitRow, type CommitRowContext } from "@/components/ui/commit-history-row"
import type { useCommitTrail } from "@/components/ui/use-commit-history"
import type { useTrailRows } from "@/components/ui/use-trail-rows"
import type { BranchInfo } from "@/lib/commit-branches"
import { isMergeRow, type Commit, type CommitGraph } from "@/lib/commit-graph"
import { commitSubject } from "@/lib/commit-message"
import { toISO } from "@/lib/time"

type Trail = ReturnType<typeof useCommitTrail>

/** The Tree's items: every commit, merges holding the commits nested under them. O(commits). */
function treeItemsOf(graph: CommitGraph): TreeItemData[] {
  const items: TreeItemData[] = []
  const nodes: TreeItemData[] = []
  for (let row = 0; row < graph.size; row += 1) {
    const commit = graph.commits[row] as Commit
    const node: TreeItemData = { value: commit.id, label: commitSubject(commit) }
    if (isMergeRow(graph, row)) node.children = []
    nodes.push(node)
    const owner = graph.owner[row] as number
    if (owner < 0) items.push(node)
    else nodes[owner]?.children?.push(node)
  }
  return items
}

function summaryOf(info: BranchInfo): CommitBranchSummary {
  const updatedAt = info.updatedAt === undefined ? undefined : toISO(info.updatedAt)
  return { name: info.name, head: info.head, ahead: info.ahead, behind: info.behind, updatedAt, state: info.state }
}

function doneCount(commits: readonly Commit[]) {
  let count = 0
  for (const commit of commits) if (commit.status !== "pending") count += 1
  return count
}

function ancestorIn(graph: CommitGraph, row: number, ids: ReadonlySet<string>) {
  for (let owner = graph.owner[row] as number; owner >= 0; owner = graph.owner[owner] as number) {
    if (ids.has((graph.commits[owner] as Commit).id)) return true
  }
  return false
}

type RowsProps = {
  trail: Trail
  details: ReadonlySet<string>
  justExpanded: ReadonlySet<string>
  context: CommitRowContext
  virtual: Omit<ReturnType<typeof useTrailRows>, "setScroller" | "anchor">
  heads: ReadonlyMap<string, readonly BranchInfo[]> | undefined
}

function Rows({ trail, details, justExpanded, context, virtual, heads }: RowsProps) {
  const { graph, visible, layout } = trail
  return virtual.segments.map((segment) => {
    if (segment.type === "gap") {
      return (
        <div key={segment.key} aria-hidden="true" data-slot="commit-history-gap" style={{ height: segment.size }} />
      )
    }
    const { index, top } = segment
    const row = visible.rows[index] as number
    const commit = graph.commits[row] as Commit
    return (
      <CommitRow
        key={commit.id}
        commit={commit}
        index={index}
        top={top}
        lanes={layout.at(index)}
        depth={graph.depth[row] as number}
        merge={isMergeRow(graph, row)}
        detailsOpen={details.has(commit.id)}
        entering={justExpanded.size > 0 && ancestorIn(graph, row, justExpanded)}
        drawIn={justExpanded.has(commit.id)}
        context={context}
        measure={virtual.measure}
        textSlot={virtual.textSlot}
        heads={heads?.get(commit.id)}
      />
    )
  })
}

export { doneCount, Rows, summaryOf, treeItemsOf }
export type { RowsProps }

